// -------------------------------------
// Common Gulp functions used by the Library CSS/JS projects.
//
// Config-agnostic: every function takes explicit sources/destinations.
// index.js is what knows about a consuming project's gulp-config.js.
// -------------------------------------

const path = require("node:path");
const crypto = require("node:crypto");
const { Transform } = require("node:stream");

const plumber = require("gulp-plumber");
const rename = require("gulp-rename");
const concat = require("gulp-concat");
const sourcemaps = require("gulp-sourcemaps");
const sassGlob = require("gulp-sass-glob");
const sass = require("gulp-sass")(require("sass"));
const stylelint = require("@ronilaukkarinen/gulp-stylelint");
const postcss = require("gulp-postcss");
const autoprefixer = require("autoprefixer");
const cssnano = require("cssnano");
const terser = require("gulp-terser");
const gulp = require("gulp");
const { ESLint } = require("eslint");

const gulpFuncs = {};

gulpFuncs.concatCSS = (sources, destination) => {
  return gulp
    .src(sources)
    .pipe(sourcemaps.init({ loadMaps: true }))
    .pipe(concat(path.basename(destination)))
    .pipe(sourcemaps.write())
    .pipe(gulp.dest(path.dirname(destination)));
};

/** Lint SCSS with Stylelint, compile it, and autoprefix the result.
 * @param {array} sources a list of files to lint and compile
 * @param {string} destination the directory into which to put the compiled results
 * @return {stream} the Node stream representing the compiled files.
 */
gulpFuncs.lintAndCompileSASS = (sources, destination) => {
  return gulp
    .src(sources)
    .pipe(plumber())
    .pipe(sourcemaps.init({ loadMaps: true, largeFile: true }))
    .pipe(sassGlob())
    .pipe(
      stylelint({
        reporters: [{ formatter: "string", console: true }],
      }),
    )
    .pipe(sass({ outputStyle: "expanded" }))
    .pipe(postcss([autoprefixer()]))
    .pipe(sourcemaps.write("./"))
    .pipe(gulp.dest(destination));
};

/**
 * Lint file globs with ESLint's own Node API (rather than a
 * `gulp-eslint*` wrapper, which tends to lag behind current ESLint
 * majors). Returns a Promise instead of a stream.
 * @param {array|string} sources globs to lint
 * @return {Promise<void>}
 */
gulpFuncs.jsLint = async (sources) => {
  const eslint = new ESLint();
  const results = await eslint.lintFiles(sources);

  const formatter = await eslint.loadFormatter("stylish");
  const output = formatter.format(results);
  // eslint-disable-next-line no-console -- printing lint results is the point of this task
  if (output) console.log(output);

  const errorCount = results.reduce((n, r) => n + r.errorCount, 0);
  if (errorCount > 0) {
    throw new Error(`ESLint found ${errorCount} error(s).`);
  }
};

/** Produce minified JavaScript files. */
gulpFuncs.jsMinify = (sources, destination) => {
  return gulp
    .src(sources)
    .pipe(plumber())
    .pipe(terser())
    .pipe(rename({ suffix: ".min" }))
    .pipe(gulp.dest(destination));
};

gulpFuncs.minifyCSS = (sources, destination) => {
  return gulp
    .src(sources)
    .pipe(sourcemaps.init({ loadMaps: true, largeFile: true }))
    .pipe(postcss([cssnano({ preset: "default" })]))
    .pipe(rename({ suffix: ".min" }))
    .pipe(sourcemaps.write("./"))
    .pipe(gulp.dest(destination));
};

// Move unminified CSS to destination.
gulpFuncs.moveCSS = (sources, destination) => {
  return gulp.src(sources).pipe(gulp.dest(destination));
};

// Record checksums of all the source files so CI/CD can later
// validate the build products against the sources.
gulpFuncs.updateSourceChecksums = (sources, checksumFile) => {
  const root = process.cwd();

  return gulp
    .src(sources)
    .pipe(
      new Transform({
        objectMode: true,
        transform(file, enc, cb) {
          const shasum = crypto.createHash("sha256");
          shasum.update(file.contents);
          const relpath = path.relative(root, file.path);
          file.contents = Buffer.from(`${shasum.digest("hex")}  ${relpath}\n`);
          cb(null, file);
        },
      }),
    )
    .pipe(concat(path.basename(checksumFile)))
    .pipe(gulp.dest(path.dirname(checksumFile)));
};

module.exports = gulpFuncs;
